window.TXB=window.TXB||{};TXB["svd/Job"]={"20:28":"تزول غلة بيته. تهراق في يوم غضبه.","20:29":"هذا نصيب الإنسان الشرير من عند الله وميراث أمره من القدير].","21:1":"فقال أيوب:","21:2":"[اسمعوا قولي سمعا وليكن هذا تعزيتكم.","21:3":"احتملوني وأنا أتكلم وبعد كلامي استهزئوا!","21:4":"أما أنا فهل شكواي من إنسان. وإن كانت فلماذا لا تضيق روحي؟","21:5":"تفرسوا في وتعجبوا وضعوا اليد على الفم.","21:6":"[عندما أتذكر أرتاع وأخذت بشري رعدة.","21:7":"لماذا تحيا الأشرار ويشيخون نعم ويتجبرون قوة؟","21:8":"نسلهم قائم أمامهم معهم وذريتهم في أعينهم.","21:9":"بيوتهم آمنة من الخوف وليس عليهم عصا الله.","21:10":"ثورهم يلقح ولا يخطئ. بقرتهم تنتج ولا تسقط.","21:11":"يسرحون مثل الغنم رضعهم وأطفالهم ترقص.","21:12":"يحملون الدف والعود ويطربون بصوت المزمار.","21:13":"يقضون أيامهم بالخير. في لحظة يهبطون إلى الهاوية.","21:14":"فيقولون لله: ابعد عنا. وبمعرفة طرقك لا نسر.","21:15":"من هو القدير حتى نعبده وماذا ننتفع إن التمسناه!.","21:16":"[هوذا ليس في يدهم خيرهم. لتبعد عني مشورة الأشرار.","21:17":"كم ينطفئ سراج الأشرار ويأتي عليهم بوارهم أو يقسم لهم أوجاعا في غضبه","21:18":"أو يكونون كالتبن قدام الريح وكالعصافة التي تسرقها الزوبعة.","21:19":"الله يخزن إثمه لبنيه. ليجازه نفسه فيعلم.","21:20":"لتنظر عيناه هلاكه ومن حمة القدير يشرب.","21:21":"فما هي مسرته في بيته بعده وقد تعين عدد شهوره؟","21:22":"[أالله يعلم معرفة وهو يقضي على العالين؟","21:23":"هذا يموت في عين كماله. كله مطمئن وساكن.","21:24":"أحواضه ملآنة لبنا ومخ عظامه طري.","21:25":"وذلك يموت بنفس مرة ولم يذق خيرا.","21:26":"كلاهما يضطجعان معا في التراب والدود يغشاهما.","21:27":"[هوذا قد علمت أفكاركم والنيات التي بها تظلمونني.","21:28":"لأنكم تقولون: أين بيت العاتي وأين خيمة مساكن الأشرار؟","21:29":"أفلم تسألوا عابري السبيل ولم تفطنوا لدلائلهم.","21:30":"إنه ليوم البوار يمسك الشرير. ليوم السخط يقادون.","21:31":"من يعلن طريقه لوجهه ومن يجازيه على ما عمل؟","21:32":"هو إلى القبور يقاد وعلى المدفن يسهر.","21:33":"حلو له طين الوادي. يزحف كل إنسان وراءه وقدامه ما لا عدد له.","21:34":"فكيف تعزونني باطلا وأجوبتكم بقيت خيانة؟].","22:1":"فأجاب أليفاز التيماني:","22:2":"[هل ينفع الإنسان الله؟ بل ينفع نفسه الفطن!","22:3":"هل من مسرة للقدير إذا تبررت أو من فائدة إذا قومت طرقك؟","22:4":"هل على تقواك يوبخك أو يدخل معك في المحاكمة؟","22:5":"أليس شرك عظيما وآثامك لا نهاية لها!","22:6":"لأنك ارتهنت أخاك بلا سبب وسلبت ثياب العراة.","22:7":"ماء لم تسق العطشان وعن الجوعان منعت خبزا.","22:8":"أما صاحب القوة فله الأرض والمترفع الوجه ساكن فيها.","22:9":"الأرامل أرسلت خاليات وذراع اليتامى انسحقت.","22:10":"لأجل ذلك حواليك فخاخ ويريعك رعب بغتة","22:11":"أو ظلمة فلا ترى وفيض المياه يغطيك.","22:12":"[هوذا الله في علو السماوات. وانظر رأس الكواكب ما أعلاه.","22:13":"فقلت: كيف يعلم الله؟ هل من وراء الضباب يقضي؟","22:14":"السحاب ستر له فلا يرى وعلى دائرة السماوات يتمشى.","22:15":"هل تحفظ طريق القدم الذي داسه رجال الإثم","22:16":"الذين قبض عليهم قبل الوقت؟ الغمر انصب على أساسهم.","22:17":"القائلين لله: ابعد عنا. وماذا يفعل القدير لهم.","22:18":"وهو قد ملأ بيوتهم خيرا. لتبعد عني مشورة الأشرار.","22:19":"الأبرار ينظرون ويفرحون والبريء يستهزئ بهم قائلين:","22:20":"ألم يبد مقاومونا وبقيتهم قد أكلتها النار؟","22:21":"[تعرف به واسلم. بذلك يأتيك خير.","22:22":"اقبل الشريعة من فمه وضع كلامه في قلبك.","22:23":"إن رجعت إلى القدير تبنى. إن أبعدت ظلما من خيمتك","22:24":"وألقيت التبر على التراب وذهب أوفير بين حصا الأودية.","22:25":"يكون القدير تبرك وفضة أتعاب لك.","22:26":"لأنك حينئذ تتلذذ بالقدير وترفع إلى الله وجهك.","22:27":"تصلي له فيستمع لك ونذورك توفيها.","22:28":"وتجزم أمرا فيثبت لك وعلى طرقك يضيء نور.","22:29":"إذا وضعوا تقول: رفع. ويخلص المنخفض العينين.","22:30":"ينجي غير البريء وينجى بطهارة يديك].","23:1":"فقال أيوب:","23:2":"[اليوم أيضا شكواي تمرد. ضربتي أثقل من تنهدي.","23:3":"من يعطيني أن أجده فآتي إلى كرسيه!","23:4":"أحسن الدعوى أمامه وأملأ فمي حججا.","1:1":"كان رجل في أرض عوص اسمه أيوب. وكان هذا الرجل كاملا ومستقيما يتقي الله ويحيد عن الشر.","1:2":"وولد له سبعة بنين وثلاث بنات.","1:3":"وكانت مواشيه سبعة آلاف من الغنم وثلاثة آلاف جمل وخمس مئة زوج بقر وخمس مئة أتان وخدمه كثيرين جدا. فكان هذا الرجل أعظم كل بني المشرق.","1:4":"وكان بنوه يذهبون ويعملون وليمة في بيت كل واحد منهم في يومه ويرسلون ويستدعون أخواتهم الثلاث ليأكلن ويشربن معهم.","1:5":"وكان لما دارت أيام الوليمة أن أيوب أرسل فقدسهم وبكر في الغد وأصعد محرقات على عددهم كلهم لأن أيوب قال: [ربما أخطأ بني وجدفوا على الله في قلوبهم]. هكذا كان أيوب يفعل كل الايام.","1:6":"وكان ذات يوم أنه جاء بنو الله ليمثلوا أمام الرب وجاء الشيطان أيضا في وسطهم.","1:7":"فقال الرب للشيطان: [من أين جئت؟] فأجاب الشيطان: [من الجولان في الأرض ومن التمشي فيها].","1:8":"فقال الرب للشيطان: [هل جعلت قلبك على عبدي أيوب؟ لأنه ليس مثله في الأرض. رجل كامل ومستقيم يتقي الله ويحيد عن الشر].","1:9":"فأجاب الشيطان: [هل مجانا يتقي أيوب الله؟","1:10":"أليس أنك سيجت حوله وحول بيته وحول كل ما له من كل ناحية؟ باركت أعمال يديه فانتشرت مواشيه في الأرض!","1:11":"ولكن ابسط يدك الآن ومس كل ما له فإنه في وجهك يجدف عليك].","1:12":"فقال الرب للشيطان: [هوذا كل ما له في يدك وإنما إليه لا تمد يدك]. ثم خرج الشيطان من أمام وجه الرب.","1:13":"وكان ذات يوم وأبناؤه وبناته يأكلون ويشربون خمرا في بيت أخيهم الأكبر","1:14":"أن رسولا جاء إلى أيوب وقال: [البقر كانت تحرث والأتن ترعى بجانبها","1:15":"فسقط عليها السبئيون وأخذوها وضربوا الغلمان بحد السيف ونجوت أنا وحدي لأخبرك].","1:16":"وبينما هو يتكلم إذ جاء آخر وقال: [نار الله سقطت من السماء فأحرقت الغنم والغلمان وأكلتهم ونجوت أنا وحدي لأخبرك].","1:17":"وبينما هو يتكلم إذ جاء آخر وقال: [الكلدانيون عينوا ثلاث فرق فهجموا على الجمال وأخذوها وضربوا الغلمان بحد السيف ونجوت أنا وحدي لأخبرك].","1:18":"وبينما هو يتكلم إذ جاء آخر وقال: [بنوك وبناتك كانوا يأكلون ويشربون خمرا في بيت أخيهم الأكبر","1:19":"وإذا ريح شديدة جاءت من عبر القفر وصدمت زوايا البيت الأربع فسقط على الغلمان فماتوا ونجوت أنا وحدي لأخبرك].","1:20":"فقام أيوب ومزق جبته وجز شعر رأسه وخر على الأرض وسجد","1:21":"وقال: [عريانا خرجت من بطن أمي وعريانا أعود إلى هناك. الرب أعطى والرب أخذ فليكن اسم الرب مباركا].","1:22":"في كل هذا لم يخطئ أيوب ولم ينسب لله جهالة.","2:1":"وكان ذات يوم أنه جاء بنو الله ليمثلوا أمام الرب وجاء الشيطان أيضا في وسطهم ليمثل أمام الرب.","2:2":"فقال الرب للشيطان: [من أين جئت؟] فأجاب الشيطان: [من الجولان في الأرض ومن التمشي فيها].","2:3":"فقال الرب للشيطان: [هل جعلت قلبك على عبدي أيوب لأنه ليس مثله في الأرض! رجل كامل ومستقيم يتقي الله ويحيد عن الشر. وإلى الآن هو متمسك بكماله وقد هيجتني عليه لأبتلعه بلا سبب].","2:4":"فأجاب الشيطان: [جلد بجلد وكل ما للإنسان يعطيه لأجل نفسه.","2:5":"ولكن ابسط الآن يدك ومس عظمه ولحمه فإنه في وجهك يجدف عليك].","2:6":"فقال الرب للشيطان: [ها هو في يدك ولكن احفظ نفسه].","2:7":"فخرج الشيطان من حضرة الرب وضرب أيوب بقرح رديء من باطن قدمه إلى هامته.","2:8":"فأخذ لنفسه شقفة ليحتك بها وهو جالس في وسط الرماد.","2:9":"فقالت له امرأته: [أنت متمسك بعد بكمالك! جدف على الله ومت!]","2:10":"فقال لها: [تتكلمين كلاما كإحدى الجاهلات! أالخير نقبل من عند الله والشر لا نقبل؟] في كل هذا لم يخطئ أيوب بشفتيه.","2:11":"فلما سمع أصحاب أيوب الثلاثة بكل الشر الذي أتى عليه جاءوا كل واحد من مكانه: أليفاز التيماني وبلدد الشوحي وصوفر النعماتي وتواعدوا أن يأتوا ليرثوا له ويعزوه.","2:12":"ورفعوا أعينهم من بعيد ولم يعرفوه فرفعوا أصواتهم وبكوا ومزق كل واحد جبته وذروا ترابا فوق رؤوسهم نحو السماء","2:13":"وقعدوا معه على الأرض سبعة أيام وسبع ليال ولم يكلمه أحد بكلمة لأنهم رأوا أن كآبته كانت عظيمة جدا.","3:1":"بعد هذا سب أيوب يومه","3:2":"وأخذ يتكلم فقال:","3:3":"[ليته هلك اليوم الذي ولدت فيه والليل الذي قال قد حبل برجل!","3:4":"ليكن ذلك اليوم ظلاما. لا يعتن به الله من فوق ولا يشرق عليه نهار.","3:5":"ليملكه الظلام وظل الموت. ليحل عليه سحاب. لترعبه كاسفات النهار.","3:6":"أما ذلك الليل فليمسكه الدجى ولا يفرح بين أيام السنة ولا يدخلن في عدد الشهور.","3:7":"هوذا ذلك الليل ليكن عاقرا! لا يسمع فيه هتاف.","3:8":"ليلعنه لاعنو اليوم المستعدون لإيقاظ التنين.","3:9":"لتظلم نجوم عشائه. لينتظر النور ولا يكن ولا ير هدب الصبح","3:10":"لأنه لم يغلق أبواب بطن أمي ولم يستر الشقاوة عن عيني.","3:11":"لم لم أمت من الرحم؟ عندما خرجت من البطن لم لم أسلم الروح؟","3:12":"لماذا أعانتني الركب ولم الثدي حتى أرضع؟","3:13":"لأني قد كنت الآن مضطجعا ساكنا. حينئذ كنت نمت مستريحا","3:14":"مع ملوك ومشيري الأرض الذين بنوا أهراما لأنفسهم","3:15":"أو مع رؤساء لهم ذهب المالئين بيوتهم فضة","3:16":"أو كسقط مطمور فلم أكن كأجنة لم يروا نورا.","3:17":"هناك يكف المنافقون عن الشغب وهناك يستريح المتعبون.","3:18":"الأسرى يطمئنون جميعا. لا يسمعون صوت المسخر.","3:19":"الصغير كما الكبير هناك والعبد حر من سيده.","3:20":"[لم يعطى لشقي نور وحياة لمري النفس؟","3:21":"الذين ينتظرون الموت وليس هو ويحفرون عليه أكثر من الكنوز","3:22":"المسرورين إلى أن يبتهجوا الفرحين عندما يجدون قبرا.","3:23":"لرجل قد خفي عليه طريقه وقد سيج الله حوله.","3:24":"لأنه مثل خبزي يأتي أنيني ومثل المياه تنسكب زفرتي","3:25":"لأني ارتعابا ارتعبت فأتاني والذي فزعت منه جاء علي.","3:26":"لم أطمئن ولم أسكن ولم أسترح وقد جاء الغضب].","4:1":"فأجاب أليفاز التيماني:","4:2":"[إن امتحن أحد كلمة معك فهل تستاء؟ ولكن من يستطيع الامتناع عن الكلام!","4:3":"ها أنت قد أرشدت كثيرين وشددت أيادي مرتخية.","4:4":"قد أقام كلامك العاثر وثبت الركب المرتعشة.","4:5":"والآن إذ جاء عليك ضجرت! إذ مسك ارتعت!","4:6":"أليست تقواك هي معتمدك ورجاؤك كمال طرقك؟","4:7":"اذكر من هلك وهو بريء وأين أبيد المستقيمون؟","4:8":"كما قد رأيت أن الحارثين إثما والزارعين شقاوة يحصدونهما.","4:9":"بنسمة الله يبيدون وبريح أنفه يفنون.","4:10":"زمجرة الأسد وصوت الزئير وأنياب الأشبال تكسرت.","4:11":"الليث هالك لعدم الفريسة وأشبال اللبوة تبددت.","4:12":"ثم إلي تسللت كلمة فقبلت أذني منها همسا.","4:13":"في الهواجس من رؤى الليل عند وقوع سبات على الناس","4:14":"أصابني رعب ورعدة فرجفت كل عظامي.","4:15":"فمرت روح على وجهي. اقشعر شعر جسدي.","4:16":"وقفت ولكني لم أعرف منظرها. شبه قدام عيني. سمعت صوتا منخفضا:","4:17":"أالإنسان أبر من الله أم الرجل أطهر من خالقه؟","4:18":"هوذا عبيده لا يأتمنهم وإلى ملائكته ينسب حماقة.","4:19":"فكم بالحري سكان بيوت من طين الذين أساسهم في التراب ويسحقون مثل العث؟","4:20":"بين الصباح والمساء يحطمون. بدون منتبه إليهم إلى الأبد يبيدون.","4:21":"أما انتزعت حبال خيامهم؟ يموتون بلا حكمة.","5:1":"[ادع الآن. فهل لك من مجيب! وإلى أي القديسين تلتفت؟","5:2":"لأن الغيظ يقتل الغبي والغيرة تميت الأحمق.","5:3":"إني رأيت الغبي يتأصل وبغتة لعنت مربضه.","5:4":"بنوه بعيدون عن الأمن وقد تحطموا في الباب ولا منقذ.","5:5":"الذين يأكل الجوعان حصيدهم ويأخذه حتى من الشوك ويشتف الظمآن ثروتهم.","5:6":"إن البلية لا تخرج من التراب والشقاوة لا تنبت من الأرض","5:7":"ولكن الإنسان مولود للمشقة كما أن الجوارح لارتفاع الجناح.","5:8":"[لكن كنت أطلب إلى الله وعلى الله أجعل أمري.","5:9":"الفاعل عظائم لا تفحص وعجائب لا تعد.","5:10":"المنزل مطرا على وجه الأرض والمرسل المياه على البراري.","5:11":"الجاعل المتواضعين في العلى فيرتفع المحزونون إلى أمن.","5:12":"المبطل أفكار المحتالين فلا تجري أيديهم قصدا.","5:13":"الآخذ الحكماء بحيلتهم فتتهور مشورة الماكرين.","5:14":"في النهار يصدمون ظلاما ويتلمسون في الظهيرة كما في الليل.","5:15":"المنجي البائس من السيف من فمهم ومن يد القوي.","5:16":"فيكون للذليل رجاء وتسد الخطية فاها.","5:17":"[هوذا طوبى لرجل يؤدبه الله. فلا ترفض تأديب القدير.","5:18":"لأنه هو يجرح ويعصب. يسحق ويداه تشفيان.","5:19":"في ست شدائد ينجيك وفي سبع لا يمسك سوء.","5:20":"في الجوع يفديك من الموت وفي الحرب من حد السيف.","5:21":"من سوط اللسان تختبأ فلا تخاف من الخراب إذا جاء.","5:22":"تضحك على الخراب والمجاعة ولا تخشى وحوش الأرض.","5:23":"لأنه مع حجارة الحقل عهدك ووحوش البرية تسالمك.","5:24":"فتعلم أن خيمتك آمنة وتتعهد مربضك ولا تفقد شيئا.","5:25":"وتعلم أن زرعك كثير وذريتك كعشب الأرض.","5:26":"تدخل المدفن في شيخوخة كرفع الكدس في أوانه.","5:27":"ها إن ذا قد بحثنا عنه. كذا هو. فاسمعه واعلم أنت لنفسك].","6:1":"فقال أيوب:","6:2":"[ليت كربي وزن ومصيبتي رفعت في الموازين جميعها.","6:3":"لأنها الآن أثقل من رمل البحر. من أجل ذلك لغا كلامي.","6:4":"لأن سهام القدير في تشرب روحي سمها. أهوال الله مصطفة ضدي.","6:5":"هل ينهق الفراء على العشب أو يخور الثور على علفه؟","6:6":"هل يؤكل المسيخ بلا ملح أو يوجد طعم في مرق البقلة؟","6:7":"عافت نفسي أن تمسها فصارت خبزي الكريه!","6:8":"[يا ليت طلبتي تأتي ويعطيني الله رجائي!","6:9":"أن يرضى الله بأن يسحقني ويطلق يده فيقطعني.","6:10":"فلا تزال تعزيتي وابتهاجي في عذاب لا يشفق أني لم أجحد كلام القدوس.","6:11":"ما هي قوتي حتى أنتظر وما هي نهايتي حتى أصبر نفسي؟","6:12":"هل قوتي قوة الحجارة؟ هل لحمي نحاس؟","6:13":"ألا إنه ليست في معونتي والمساعدة مطرودة عني!","6:14":"[حق المحزون معروف من صاحبه وإن ترك خشية القدير.","6:15":"أما إخواني فقد غدروا مثل الغدير. مثل ساقية الوديان يعبرون.","6:16":"التي هي عكرة من البرد ويختفي فيها الجليد.","6:17":"إذا جرت انقطعت. إذا حميت جفت من مكانها.","6:18":"تحيد القوافل عن طريقها تدخل التيه فتهلك.","6:19":"نظرت قوافل تيماء. مواكب سبأ رجوها.","6:20":"خزوا في ما كانوا مطمئنين. جاءوا إليها فخجلوا.","6:21":"فالآن قد صرتم مثلها. رأيتم ضربة ففزعتم.","6:22":"هل قلت: أعطوني شيئا أو من مالكم ارشوا من أجلي","6:23":"أو نجوني من يد الخصم أو من يد العتاة افدوني؟","6:24":"علموني فأنا أسكت وفهموني في أي شيء ضللت.","6:25":"ما أشد الكلام المستقيم وأما التوبيخ منكم فعلى ماذا يبرهن؟","6:26":"هل تحسبون أن توبخوا كلمات وكلام اليائس للريح!","6:27":"بل تلقون على اليتيم وتحفرون حفرة لصاحبكم!","6:28":"والآن تفرسوا في فإني على وجوهكم لا أكذب.","6:29":"ارجعوا. لا يكونن ظلم. ارجعوا أيضا. فيه حقي.","6:30":"هل في لساني ظلم أم حنكي لا يميز فسادا؟","7:1":"[أليست حياة الإنسان جهادا على الأرض وكأيام الأجير أيامه؟","7:2":"كما يتشوق العبد إلى الظل وكما يترجى الأجير أجرته","7:3":"هكذا تعين لي أشهر سوء وليالي شقاء قسمت لي.","7:4":"إذا اضطجعت أقول متى أقوم. الليل يطول وأشبع قلقا حتى الصبح.","7:5":"لبس لحمي الدود مع الطين. جلدي تشقق وتقيح.","7:6":"أيامي أسرع من المكوك وتنتهي بغير رجاء.","7:7":"[اذكر أن حياتي إنما هي ريح وعيني لا تعود ترى خيرا.","7:8":"لا تراني عين ناظري. عيناك علي ولست أنا!","7:9":"السحاب يضمحل ويزول. هكذا الذي ينزل إلى الهاوية لا يصعد.","7:10":"لا يرجع بعد إلى بيته ولا يعرفه مكانه بعد.","7:11":"أنا أيضا لا أمنع فمي. أتكلم بضيق روحي. أشكو بمرارة نفسي.","7:12":"أبحر أنا أم تنين حتى جعلت علي حارسا؟","7:13":"إن قلت: فراشي يعزيني مضجعي ينزع كربتي","7:14":"تريعني بالأحلام وترهبني برؤى","7:15":"فاختارت نفسي الخنق والموت على عظامي هذه.","7:16":"قد ذبت. لا إلى الأبد أحيا. كف عني لأن أيامي نفخة!","7:17":"ما هو الإنسان حتى تعتبره وحتى تضع عليه قلبك","7:18":"وتتعهده كل صباح وكل لحظة تمتحنه!","7:19":"حتى متى لا تلتفت عني ولا ترخيني ريثما أبلع ريقي؟","7:20":"أأخطأت؟ ماذا أفعل لك يا رقيب الناس! لماذا جعلتني هدفا لك حتى أكون على نفسي حملا!","7:21":"ولماذا لا تغفر ذنبي ولا تزيل إثمي لأني الآن أضطجع في التراب؟ تطلبني فلا أكون!].","8:1":"فأجاب بلدد الشوحي:","8:2":"[إلى متى تقول هذا وتكون أقوالك ريحا شديدة!","8:3":"هل الله يعوج القضاء أو القدير يعكس الحق؟","8:4":"إذ أخطأ إليه بنوك دفعهم إلى يد معصيتهم.","8:5":"فإن بكرت أنت إلى الله وتضرعت إلى القدير -","8:6":"إن كنت أنت زكيا مستقيما فإنه الآن يتنبه لك ويسلم مسكن برك.","8:7":"وإن تكن أولاك صغيرة فآخرتك تكثر جدا.","8:8":"[اسأل القرون الأولى وتأكد مباحث آبائهم.","8:9":"لأننا نحن من أمس ولا نعلم لأن أيامنا على الأرض ظل.","8:10":"فهلا يعلمونك. يقولون لك ومن قلوبهم يخرجون أقوالا قائلين","8:11":"هل ينمو البردي في غير المستنقع أو تنبت الحلفاء بلا ماء؟","8:12":"وهو بعد في نضارته لم يقطع ييبس قبل كل العشب.","8:13":"هكذا سبل كل الناسين الله ورجاء الفاجر يخيب","8:14":"فينقطع اعتماده ومتكله بيت العنكبوت!","8:15":"يستند إلى بيته فلا يثبت. يتمسك به فلا يقوم.","8:16":"هو رطب تجاه الشمس وعلى جنته تنبت أغصانه.","8:17":"وأصوله مشتبكة في الرجمة فترى محل الحجارة.","8:18":"إن اقتلعه من مكانه يجحده قائلا: ما رأيتك.","8:19":"هذا هو فرح طريقه ومن التراب ينبت آخر.","8:20":"[هوذا الله لا يرفض الكامل ولا يأخذ بيد فاعلي الشر.","8:21":"عندما يملأ فمك ضحكا وشفتيك هتافا","8:22":"يلبس مبغضوك خزيا. أما خيمة الأشرار فلا تكون].","9:1":"فقال أيوب:","9:2":"[صحيح. قد علمت أنه كذا. فكيف يتبرر الإنسان عند الله؟","9:3":"إن شاء أن يحاجه لا يجيبه عن واحد من ألف.","9:4":"هو حكيم القلب وشديد القوة. من تصلب عليه فسلم؟","9:5":"المزحزح الجبال ولا تعلم. الذي يقلبها في غضبه","9:6":"المزعزع الأرض من مقرها فتتزلزل أعمدتها","9:7":"الآمر الشمس فلا تشرق ويختم على النجوم.","9:8":"الباسط السماوات وحده والماشي على أعالي البحر.","9:9":"صانع النعش والجبار والثريا ومخادع الجنوب.","9:10":"فاعل عظائم لا تفحص وعجائب لا تعد.","9:11":"[هوذا يمر علي ولا أراه ويجتاز فلا أشعر به.","9:12":"إذا خطف فمن يرده ومن يقول له: ماذا تفعل؟","9:13":"الله لا يرد غضبه. ينحني تحته أعوان رهب.","9:14":"كم بالأقل أنا أجاوبه وأختار كلامي معه.","9:15":"لأني وإن تبررت لا أجاوب بل أسترحم دياني.","9:16":"لو دعوت فاستجاب لي لما آمنت بأنه سمع صوتي.","9:17":"ذاك الذي يسحقني بالعاصفة ويكثر جروحي بلا سبب.","9:18":"لا يدعني آخذ نفسي ولكن يشبعني مرائر.","9:19":"إن كان من جهة قوة القوي يقول: هئنذا. وإن كان من جهة القضاء يقول: من يحاكمني؟","9:20":"إن تبررت يحكم علي فمي؟ وإن كنت كاملا يستذنبني.","9:21":"[كامل أنا. لا أبالي بنفسي. رذلت حياتي.","9:22":"هي واحدة. لذلك قلت إن الكامل والشرير هو يفنيهما.","9:23":"إذا قتل السوط بغتة يستهزئ بتجربة الأبرياء.","9:24":"الأرض مسلمة ليد الشرير. يغشي وجوه قضاتها. وإن لم يكن هو فإذا من؟","9:25":"أيامي أسرع من عداء تفر ولا ترى خيرا.","9:26":"تمر مع سفن البردي. كنسر ينقض إلى صيده.","9:27":"إن قلت: أنسى كربتي. أطلق وجهي وأبتسم","9:28":"أخاف من كل أوجاعي عالما أنك لا تبرئني.","9:29":"أنا مستذنب فلماذا أتعب عبثا؟","9:30":"ولو اغتسلت في الثلج ونظفت يدي بالأشنان","9:31":"فإنك في النقع تغمسني حتى تكرهني ثيابي.","9:32":"لأنه ليس هو إنسانا مثلي فأجاوبه فنأتي جميعا إلى المحاكمة.","9:33":"ليس بيننا مصالح يضع يده على كلينا!","9:34":"ليرفع عني عصاه ولا يبغتني رعبه.","9:35":"إذا أتكلم ولا أخافه. لأني لست هكذا عند نفسي.","10:1":"[قد كرهت نفسي حياتي. أسيب شكواي. أتكلم في مرارة نفسي","10:2":"قائلا لله: لا تستذنبني. فهمني لماذا تخاصمني!","10:3":"أحسن عندك أن تظلم أن ترذل عمل يديك وتشرق على مشورة الأشرار؟","10:4":"ألك عينا بشر أم كنظر الإنسان تنظر؟","10:5":"أأيامك كأيام الإنسان أم سنوك كأيام الرجل","10:6":"حتى تبحث عن إثمي وتفتش على خطيتي؟","10:7":"في علمك أني لست مذنبا ولا منقذ من يدك.","10:8":"[يداك كونتاني وصنعتاني كلي جميعا. أفتبتلعني؟","10:9":"اذكر أنك جبلتني كالطين. أفتعيدني إلى التراب؟","10:10":"ألم تصبني كاللبن وخثرتني كالجبن؟","10:11":"كسوتني جلدا ولحما فنسجتني بعظام وعصب.","10:12":"منحتني حياة ورحمة وحفظت عنايتك روحي.","10:13":"لكنك كتمت هذه في قلبك. علمت أن هذا عندك.","10:14":"إن أخطأت تلاحظني ولا تبرئني من إثمي.","10:15":"إن أذنبت فويل لي. وإن تبررت لا أرفع رأسي. إني شبعان هوانا وناظر مذلتي.","10:16":"وإن ارتفع رأسي تصطادني كأسد ثم تعود وتتجبر علي!","10:17":"تجدد شهودك تجاهي وتزيد غضبك علي. مصائب وجيش ضدي.","10:18":"[فلماذا أخرجتني من الرحم؟ كنت قد أسلمت الروح ولم ترني عين!","10:19":"فكنت كأني لم أكن فأقاد من الرحم إلى القبر.","10:20":"أليست أيامي قليلة؟ اترك! كف عني فأبتسم قليلا","10:21":"قبل أن أذهب ولا أعود. إلى أرض ظلمة وظل الموت","10:22":"أرض ظلام مثل دجى ظل الموت وبلا ترتيب وإشراقها كالدجى].","11:1":"فأجاب صوفر النعماتي:","11:2":"[أكثرة الكلام لا يجاوب أم رجل مهذار يتبرر؟","11:3":"أصلفك يفحم الناس أم تلغو وليس من يخزيك؟","11:4":"إذ تقول: تعليمي زكي وأنا بار في عينيك.","11:5":"ولكن يا ليت الله يتكلم ويفتح شفتيه معك","11:6":"ويعلن لك خفيات الحكمة! إنها مضاعفة الفهم فتعلم أن الله يغرمك بأقل من إثمك.","11:7":"[أإلى عمق الله تتصل أم إلى نهاية القدير تنتهي؟","11:8":"هو أعلى من السماوات فماذا عساك أن تفعل؟ أعمق من الهاوية فماذا تدري؟","11:9":"أطول من الأرض طوله وأعرض من البحر.","11:10":"إن بطش أو أغلق أو جمع فمن يرده؟","11:11":"لأنه هو يعلم أناس السوء ويبصر الإثم فهل لا ينتبه؟","11:12":"أما الرجل ففارغ عديم الفهم وكجحش الفرا يولد الإنسان.","11:13":"[إن أعددت أنت قلبك وبسطت إليه يديك.","11:14":"إن أبعدت الإثم الذي في يدك ولا يسكن الظلم في خيمتك","11:15":"حينئذ ترفع وجهك بلا عيب وتكون ثابتا ولا تخاف.","11:16":"لأنك تنسى المشقة. كمياه عبرت تذكرها.","11:17":"وفوق الظهيرة يقوم حظك. الظلام يتحول صباحا.","11:18":"وتطمئن لأنه يوجد رجاء. تتجسس حولك وتضطجع آمنا.","11:19":"وتربض وليس من يزعج ويتضرع إلى وجهك كثيرون.","11:20":"أما عيون الأشرار فتتلف وملجأهم يبيد ورجاؤهم تسليم النفس].","12:1":"فقال أيوب:","12:2":"[صحيح إنكم أنتم شعب ومعكم تموت الحكمة!","12:3":"غير أنه لي فهم مثلكم. لست أنا دونكم. ومن ليس عنده مثل هذه؟","12:4":"رجلا أضحوكة لصاحبه صرت. دعا الله فاستجابه. أضحوكة هو الصديق الكامل.","12:5":"للمبتلي هوان في أفكار المطمئن مهيأ لمن زلت قدمه.","12:6":"خيام المخربين مستريحة والذين يغيظون الله مطمئنون الذين يأتون بإلههم في يدهم!","12:7":"[فاسأل البهائم فتعلمك وطيور السماء فتخبرك.","12:8":"أو كلم الأرض فتعلمك ويحدثك سمك البحر.","12:9":"من لا يعلم من كل هؤلاء أن يد الرب صنعت هذا!","12:10":"الذي بيده نفس كل حي وروح كل البشر.","12:11":"أفليست الأذن تمتحن الأقوال كما أن الحنك يستطعم طعامه؟","12:12":"عند الشيب حكمة وطول الأيام فهم.","12:13":"[عنده الحكمة والقدرة. له المشورة والفطنة.","12:14":"هوذا يهدم فلا يبنى. يغلق على إنسان فلا يفتح.","12:15":"يمنع المياه فتيبس. يطلقها فتقلب الأرض.","12:16":"عنده العز والفهم. له المضل والمضل.","12:17":"يذهب بالمشيرين أسرى ويحمق القضاة.","12:18":"يحل مناطق الملوك ويشد أحقاءهم بوثاق.","12:19":"يذهب بالكهنة أسرى ويقلب الأقوياء.","12:20":"يقطع كلام الأمناء وينزع ذوق الشيوخ.","12:21":"يلقي هوانا على الشرفاء ويرخي منطقة الأشداء.","12:22":"يكشف العمائق من الظلام ويخرج ظل الموت إلى النور.","12:23":"يكثر الأمم ثم يبيدها. يوسع للأمم ثم يشتتها.","12:24":"ينزع عقول رؤساء شعب الأرض ويضلهم في تيه بلا طريق.","12:25":"يتلمسون في الظلام وليس نور ويرنحهم مثل السكران.","13:1":"[هذا كله رأته عيني. سمعته أذني وفطنت به.","13:2":"ما تعرفونه عرفته أنا أيضا. لست دونكم.","13:3":"ولكني أريد أن أكلم القدير وأن أحاكم إلى الله.","13:4":"أما أنتم فملفقو كذب. أطباء بطالون كلكم.","13:5":"ليتكم تصمتون صمتا. يكون ذلك لكم حكمة.","13:6":"اسمعوا الآن حجتي واصغوا إلى دعاوي شفتي.","13:7":"أتقولون لأجل الله ظلما وتتكلمون بغش لأجله؟","13:8":"أتحابون وجهه أم عن الله تخاصمون؟","13:9":"أخير لكم أن يفحصكم أم تخاتلونه كما يخاتل الإنسان؟","13:10":"توبيخا يوبخكم إن حابيتم الوجوه خفية.","13:11":"فهلا يرهبكم جلاله ويسقط عليكم رعبه!","13:12":"خطبكم أمثال رماد وحصونكم حصون من طين!","13:13":"[اسكتوا عني فأتكلم أنا وليصبني مهما أصاب.","13:14":"لماذا آخذ لحمي بأسناني وأضع نفسي في كفي؟","13:15":"هوذا يقتلني. لا أنتظر شيئا. فقط أزكي طريقي قدامه.","13:16":"فهذا يعود إلى خلاصي أن الفاجر لا يأتي قدامه.","13:17":"سمعا اسمعوا أقوالي وتصريحي بمسامعكم.","13:18":"هئنذا قد أحسنت الدعوى. أعلم أني أتبرر.","13:19":"من هو الذي يخاصمني حتى أصمت الآن وأسلم الروح؟","13:20":"إنما أمرين لا تفعل بي فحينئذ لا أختفي من حضرتك.","13:21":"أبعد يديك عني ولا تدع هيبتك ترعبني","13:22":"ثم ادع فأنا أجيب أو أتكلم فتجاوبني.","13:23":"كم لي من الآثام والخطايا. أعلمني ذنبي وخطيتي.","13:24":"لماذا تحجب وجهك وتحسبني عدوا لك؟","13:25":"أترعب ورقة مندفعة وتطارد قشا يابسا!","13:26":"لأنك كتبت علي أمورا مرة وورثتني آثام صباي","13:27":"فجعلت رجلي في المقطرة ولاحظت جميع مسالكي وعلى أصول رجلي نبشت.","13:28":"وأنا كمتسوس يبلى كثوب أكله العث.","14:1":"[الإنسان مولود المرأة قليل الأيام وشبعان تعبا.","14:2":"يخرج كالزهر ثم يذوي ويبرح كالظل ولا يقف.","14:3":"فعلى مثل هذا حدقت عينيك وإياي أحضرت إلى المحاكمة معك.","14:4":"من يخرج الطاهر من النجس؟ لا أحد!","14:5":"إن كانت أيامه محدودة وعدد أشهره عندك وقد عينت أجله فلا يتجاوزه","14:6":"فأقصر عنه ليستريح إلى أن يسر كالأجير بانتهاء يومه.","14:7":"[لأن للشجرة رجاء. إن قطعت تخلف أيضا ولا تعدم أغصانها.","14:8":"ولو قدم في الأرض أصلها ومات في التراب جذعها","14:9":"فمن رائحة الماء تفرخ وتنبت فروعا كالغرس.","14:10":"أما الرجل فيموت ويبلى. الإنسان يسلم الروح فأين هو!","14:11":"قد تنفد المياه من البحر والنهر ينشف ويجف","14:12":"والإنسان يضطجع ولا يقوم. لا يستيقظون حتى لا تبقى السماوات ولا ينتبهون من نومهم.","14:13":"ليتك تواريني في الهاوية وتخفيني إلى أن ينصرف غضبك وتعين لي أجلا فتذكرني.","14:14":"إن مات رجل أفيحيا؟ كل أيام جهادي أصبر إلى أن يأتي بدلي.","14:15":"تدعو فأنا أجيبك. تشتاق إلى عمل يدك.","14:16":"أما الآن فتحصي خطواتي! ألا تحافظ على خطيتي.","14:17":"معصيتي مختوم عليها في صرة وتلفق علي فوق إثمي.","14:18":"[إن الجبل الساقط ينتثر والصخر يزحزح من مكانه.","14:19":"الحجارة تبليها المياه وتجرف سيولها تراب الأرض. وكذلك أنت تبيد رجاء الإنسان.","14:20":"تتجبر عليه أبدا فيذهب. تشوه وجهه وتطرده.","14:21":"يكرم بنوه ولا يعلم أو يصغرون ولا يفهم بهم.","14:22":"إنما على ذاته يتوجع لحمه وعلى ذاتها تنوح نفسه].","15:1":"فأجاب أليفاز التيماني:","15:2":"[ألعل الحكيم يجيب عن معرفة باطلة ويملأ بطنه من ريح شرقية","15:3":"فيحتج بكلام لا يفيد وبأحاديث لا ينتفع بها!","15:4":"أما أنت فتنافي المخافة وتناقض التقوى لدى الله.","15:5":"لأن فمك يذيع إثمك وتختار لسان المحتالين.","15:6":"إن فمك يستذنبك لا أنا وشفتاك تشهدان عليك.","15:7":"[أصورت أول الناس أم أبدئت قبل التلال!","15:8":"هل أصغيت في مجلس الله أو قصرت الحكمة على نفسك!","15:9":"ماذا تعرفه ولا نعرفه نحن وماذا تفهم وليس هو عندنا؟","15:10":"عندنا الشيخ والأشيب أكبر أياما من أبيك.","15:11":"أقليلة عندك تعزيات الله والكلام معك بالرفق!","15:12":"[لماذا يأخذك قلبك ولماذا تختلج عيناك","15:13":"حتى ترد على الله وتخرج من فمك أقوالا؟","15:14":"من هو الإنسان حتى يزكو أو مولود المرأة حتى يتبرر؟","15:15":"هوذا قديسوه لا يأتمنهم والسماوات غير طاهرة بعينيه -","15:16":"فبالحري مكروه وفاسد الإنسان الشارب الإثم كالماء!","15:17":"[أبين لك. اسمع لي فأحدث بما رأيته.","15:18":"ما أخبر به حكماء عن آبائهم فلم يكتموه.","15:19":"الذين لهم وحدهم أعطيت الأرض ولم يعبر بينهم غريب.","15:20":"الشرير هو يتلوى كل أيامه وكل عدد السنين المعدودة للعاتي.","15:21":"صوت رعوب في أذنيه. في ساعة سلام يأتيه المخرب.","15:22":"لا يأمل الرجوع من الظلمة وهو مرتقب للسيف.","15:23":"تائه هو لأجل الخبز حيثما يجده ويعلم أن يوم الظلمة مهيأ بين يديه.","15:24":"يرهبه الضر والضيق. يتجبران عليه كملك مستعد للوغى.","15:25":"لأنه مد على الله يده وعلى القدير تجبر","15:26":"هاجما عليه متصلب العنق بتروسه الغليظة.","15:27":"لأنه قد كسا وجهه سمنا وربى شحما على كليتيه","15:28":"فيسكن مدنا خربة بيوتا غير مسكونة عتيدة أن تصير رجما.","15:29":"لا يستغني ولا تثبت ثروته ولا يمتد في الأرض مقتناه.","15:30":"لا تزول عنه الظلمة. أغصانه تيبسها السموم وبنفخة فمه يزول.","15:31":"لا يتكل على السوء. يضل. لأن السوء يكون أجرته.","15:32":"قبل يومه يتوفى وسعفه لا يخضر.","15:33":"يساقط كالكرمة حصرمه وينثر كالزيتون زهره.","15:34":"لأن جماعة الفجار عاقر والنار تأكل خيام الرشوة.","15:35":"حبل شقاوة وولد إثما وبطنه أنشأ غشا].","16:1":"فقال أيوب:","16:2":"[قد سمعت كثيرا مثل هذا. معزون متعبون كلكم!","16:3":"هل من نهاية لكلام فارغ. أو ماذا يهيجك حتى تجاوب؟","16:4":"أنا أيضا أستطيع أن أتكلم مثلكم لو كانت أنفسكم مكان نفسي وأن أسرد عليكم أقوالا وأهز رأسي إليكم.","16:5":"بل كنت أشددكم بفمي وتعزية شفتي تمسككم.","16:6":"[إن تكلمت لم تمتنع كآبتي. وإن سكت فماذا يذهب عني؟","16:7":"إنه الآن ضجرني. خربت كل جماعتي.","16:8":"قبضت علي. وجد شاهد. قام علي هزالي يجاوب في وجهي.","16:9":"غضبه افترسني واضطهدني. حرق علي أسنانه. عدوي يحدد عينيه علي.","16:10":"فغروا علي أفواههم. لطموني على فكي تعييرا. تعاونوا علي جميعا.","16:11":"دفعني الله إلى الظالم وفي أيدي الأشرار طرحني.","16:12":"كنت مستريحا فزعزعني وأمسك بقفاي فحطمني ونصبني له هدفا.","16:13":"أحاطت بي رماة سهامه. شق كليتي ولم يشفق. سفك مرارتي على الأرض.","16:14":"يقتحمني اقتحاما على اقتحام. يهجم علي كجبار.","16:15":"خطت مسحا على جلدي ودسست في التراب قرني.","16:16":"احمر وجهي من البكاء وعلى هدبي ظل الموت.","16:17":"مع أنه لا ظلم في يدي وصلاتي خالصة.","16:18":"[يا أرض لا تغطي دمي ولا يكن مكان لصراخي.","16:19":"أيضا الآن هوذا في السماوات شهيدي وشاهدي في الأعالي.","16:20":"المستهزئون بي هم أصحابي. لله تقطر عيني","16:21":"لكي يحاكم الإنسان عند الله كابن آدم لدى صاحبه.","16:22":"إذا مضت سنون قليلة أسلك في طريق لا أعود منها.","17:1":"[روحي تلفت. أيامي انطفأت. إنما القبور لي.","17:2":"[لولا المخاتلون عندي وعيني تبيت على مشاجراتهم.","17:3":"كن ضامني عند نفسك. من هو الذي يصفق يدي؟","17:4":"لأنك منعت قلبهم عن الفطنة. لأجل ذلك لا ترفعهم.","17:5":"الذي يسلم الأصحاب للسلب تتلف عيون بنيه.","17:6":"أوقفني مثلا للشعوب وصرت للبصق في الوجه.","17:7":"كلت عيني من الحزن وأعضائي كلها كالظل.","17:8":"يتعجب المستقيمون من هذا والبرئ يقوم على الفاجر.","17:9":"أما الصديق فيستمسك بطريقه والطاهر اليدين يزداد قوة.","17:10":"[ولكن ارجعوا كلكم وتعالوا فلا أجد فيكم حكيما.","17:11":"أيامي قد عبرت. مقاصدي إرث قلبي قد انتزعت.","17:12":"يجعلون الليل نهارا نورا قريبا للظلمة.","17:13":"إذا رجوت الهاوية بيتا لي وفي الظلام مهدت فراشي","17:14":"وقلت للقبر: أنت أبي وللدود: أنت أمي وأختي","17:15":"فأين إذا آمالي؟ آمالي من يعاينها!","17:16":"تهبط إلى مغاليق الهاوية إذ ترتاح معا في التراب]","18:1":"فأجاب بلدد الشوحي:","18:2":"[إلى متى تضعون أشراكا للكلام؟ تعقلوا وبعد نتكلم.","18:3":"لماذا حسبنا كالبهيمة وتنجسنا في عيونكم؟","18:4":"يا أيها المفترس نفسه في غيظه هل لأجلك تخلى الأرض أو يزحزح الصخر من مكانه؟","18:5":"[نعم! نور الأشرار ينطفئ ولا يضيء لهيب ناره.","18:6":"النور يظلم في خيمته وسراجه فوقه ينطفئ.","18:7":"تقصر خطوات قوته وتصرعه مشورته.","18:8":"لأن رجليه تدفعانه في الفخ فيمشي إلى شبكة.","18:9":"يمسك الفخ بعقبه وتتمكن منه الشرك.","18:10":"حبل مطمور له في الأرض ومصيدته في السبيل.","18:11":"ترهبه أهوال من حوله وتذعره عند رجليه.","18:12":"تكون قوته جائعة والبوار مهيأ بجانبه.","18:13":"يأكل أعضاء جسده. يأكل أعضاءه بكر الموت.","18:14":"ينقطع عن خيمته عن اعتماده ويساق إلى ملك الأهوال.","18:15":"يسكن في خيمته من ليس له. يذر على مربضه كبريت.","18:16":"من تحت تيبس أصوله ومن فوق يقطع فرعه.","18:17":"ذكره يبيد من الأرض ولا اسم له على وجه البر.","18:18":"يدفع من النور إلى الظلمة ومن المسكونة يطرد.","18:19":"لا نسل ولا ذرية له بين شعبه ولا باق في منازله.","18:20":"يتعجب من يومه المتأخرون ويقشعر الأقدمون.","18:21":"إنما تلك مساكن فاعلي الشر وهذا مقام من لا يعرف الله].","19:1":"فقال أيوب","19:2":"[حتى متى تعذبون نفسي وتسحقونني بالكلام.","19:3":"هذه عشر مرات أخزيتموني. لم تخجلوا من أن تعنفوني.","19:4":"وهبني ضللت حقا. علي تستقر ضلالتي!","19:5":"إن كنتم بالحق تستكبرون علي فثبتوا علي عاري.","19:6":"فاعلموا إذا أن الله قد عوجني ولف علي أحبولته.","19:7":"ها إني أصرخ ظلما فلا أستجاب. أدعو وليس حكم.","19:8":"قد حوط طريقي فلا أعبر وعلى سبلي جعل ظلاما.","19:9":"أزال عني كرامتي ونزع تاج رأسي.","19:10":"هدمني من كل جهة فذهبت وقلع مثل شجرة رجائي","19:11":"وأضرم علي غضبه وحسبني كأعدائه.","19:12":"معا جاءت غزاته وأعدوا علي طريقهم وحلوا حول خيمتي.","19:13":"قد أبعد عني إخوتي. ومعارفي زاغوا عني.","19:14":"أقاربي قد خذلوني والذين عرفوني نسوني.","19:15":"نزلاء بيتي وإمائي يحسبونني أجنبيا. صرت في أعينهم غريبا.","19:16":"عبدي دعوت فلم يجب. بفمي تضرعت إليه.","19:17":"نكهتي مكروهة عند امرأتي ومنتنة عند أبناء أحشائي.","19:18":"الأولاد أيضا قد رذلوني. إذا قمت يتكلمون علي.","19:19":"كرهني كل رجالي والذين أحببتهم انقلبوا علي.","19:20":"عظمي قد لصق بجلدي ولحمي ونجوت بجلد أسناني.","19:21":"تراءفوا! تراءفوا أنتم علي يا أصحابي لأن يد الله قد مستني.","19:22":"لماذا تطاردونني كما الله ولا تشبعون من لحمي؟","19:23":"[ليت كلماتي الآن تكتب. يا ليتها رسمت في سفر","19:24":"ونقرت إلى الأبد في الصخر بقلم حديد وبرصاص.","19:25":"أما أنا فقد علمت أن وليي حي والآخر على الأرض يقوم","19:26":"وبعد أن يفنى جلدي هذا وبدون جسدي أرى الله.","19:27":"الذي أراه أنا لنفسي وعيناي تنظران وليس آخر. إلى ذلك تتوق كليتاي في جوفي.","19:28":"فإنكم تقولون: لماذا نطارده؟ والكلام الأصلي يوجد عندي.","19:29":"خافوا على أنفسكم من السيف لأن الغيظ من آثام السيف. لكي تعلموا ما هو القضاء].","20:1":"فأجاب صوفر النعماتي:","20:2":"[من أجل ذلك هواجسي تجيبني ولهذا هيجاني في.","20:3":"تعيير توبيخي أسمع. وروح من فهمي يجيبني.","20:4":"[أما علمت هذا من القديم منذ وضع الإنسان على الأرض:","20:5":"أن هتاف الأشرار من قريب وفرح الفاجر إلى لحظة!","20:6":"ولو بلغ السماوات طوله ومس رأسه السحاب","20:7":"كجلته إلى الأبد يبيد. الذين رأوه يقولون: أين هو؟","20:8":"كالحلم يطير فلا يوجد ويطرد كطيف الليل.","20:9":"عين أبصرته لا تعود تراه ومكانه لن يراه بعد.","20:10":"بنوه يترضون الفقراء ويداه تردان ثروته.","20:11":"عظامه ملآنة قوة ومعه في التراب تضطجع.","20:12":"إن حلا في فمه الشر وأخفاه تحت لسانه","20:13":"أشفق عليه ولم يتركه بل حبسه وسط حنكه","20:14":"فخبزه في أمعائه يتحول! مرارة أصلال في بطنه.","20:15":"قد بلع ثروة فيتقيأها. الله يطردها من بطنه.","20:16":"سم الأصلال يرضع. يقتله لسان الأفعى.","20:17":"لا يرى الجداول أنهار سواقي عسل ولبن.","20:18":"يرد تعبه ولا يبلعه. وبمكسب تجارته لا يفرح.","20:19":"لأنه رضض المساكين وتركهم واغتصب بيتا ولم يبنه.","20:20":"لأنه لم يعرف في بطنه قناعة لا ينجو بمشتهاه.","20:21":"ليست من أكله بقية لأجل ذلك لا يدوم خيره.","20:22":"مع ملء رغده يتضايق. تأتي عليه يد كل شقي.","20:23":"يكون عندما يملأ بطنه أن الله يرسل عليه حمو غضبه ويمطره عليه عند طعامه.","20:24":"يفر من سلاح حديد. تخرقه قوس نحاس.","20:25":"جذبه فخرج من بطنه والبارق من مرارته مرق. عليه رعوب.","20:26":"كل ظلمة مختبأة لذخائره. تأكله نار لم تنفخ. ترعى البقية في خيمته.","20:27":"السماوات تعلن إثمه والأرض تنهض عليه.","23:5":"فأعرف الأقوال التي بها يجيبني وأفهم ما يقوله لي.","23:6":"أبكثرة قوة يخاصمني؟ كلا! ولكنه كان ينتبه إلي.","23:7":"هنالك كان يحاجه المستقيم وكنت أنجو إلى الأبد من قاضي.","23:8":"هئنذا أذهب شرقا فليس هو هناك وغربا فلا أشعر به","23:9":"شمالا حيث عمله فلا أنظره. يتعطف الجنوب فلا أراه.","23:10":"[لأنه يعرف طريقي. إذا جربني أخرج كالذهب.","23:11":"بخطواته استمسكت رجلي. حفظت طريقه ولم أحد.","23:12":"من وصية شفتيه لم أبرح. أكثر من فريضتي ذخرت كلام فمه.","23:13":"أما هو فوحده فمن يرده؟ ونفسه تشتهي فيفعل.","23:14":"لأنه يتمم المفروض علي وكثير مثل هذه عنده.","23:15":"من أجل ذلك أرتاع قدامه. أتأمل فأرتعب منه.","23:16":"لأن الله قد أضعف قلبي والقدير روعني.","23:17":"لأني لم أقطع قبل الظلام ومن وجهي لم يغط الدجى.","24:1":"[لماذا إذ لم تختبئ الأزمنة من القدير لا يرى عارفوه يومه؟","24:2":"ينقلون التخوم. يغتصبون قطيعا ويرعونه.","24:3":"يستاقون حمار اليتامى ويرتهنون ثور الأرملة.","24:4":"يصدون الفقراء عن الطريق. مساكين الأرض يختبئون جميعا.","24:5":"ها هم كالفراء في القفر يخرجون إلى عملهم يبكرون للطعام. البادية لهم خبز لأولادهم.","24:6":"في الحقل يحصدون علفهم ويعللون كرم الشرير.","24:7":"يبيتون عراة بلا لبس وليس لهم كسوة في البرد.","24:8":"يبتلون من مطر الجبال ولعدم الملجإ يعتنقون الصخر.","24:9":"[يخطفون اليتيم عن الثدي ومن المساكين يرتهنون.","24:10":"عراة يذهبون بلا لبس وجائعين يحملون حزما.","24:11":"يعصرون الزيت داخل أسوارهم. يدوسون المعاصر ويعطشون.","24:12":"من الوجع أناس يئنون ونفس الجرحى تستغيث والله لا ينتبه إلى الظلم.","24:13":"[أولئك يكونون بين المتمردين على النور. لا يعرفون طرقه ولا يلبثون في سبله.","24:14":"مع النور يقوم القاتل. يقتل المسكين والفقير وفي الليل يكون كاللص.","24:15":"وعين الزاني تلاحظ العشاء. يقول: لا تراقبني عين. فيجعل سترا على وجهه.","24:16":"ينقبون البيوت في الظلام. في النهار يغلقون على أنفسهم. لا يعرفون النور.","24:17":"لأنه سواء عليهم الصباح وظل الموت. لأنهم يعلمون أهوال ظل الموت.","24:18":"خفيف هو على وجه المياه. ملعون نصيبهم في الأرض. لا يتوجه إلى طريق الكروم.","24:19":"القحط والقيظ يذهبان بمياه الثلج كذا الهاوية بالذين أخطأوا.","24:20":"تنساه الرحم يستحليه الدود. لا يذكر بعد وينكسر الأثيم كشجرة.","24:21":"يسيء إلى العاقر التي لم تلد ولا يحسن إلى الأرملة.","24:22":"يمسك الأعزاء بقوته. يقوم فلا يأمن أحد بحياته.","24:23":"يعطيه طمأنينة فيتوكل ولكن عيناه على طرقهم.","24:24":"يترفعون قليلا ثم لا يكونون ويحطون. كالكل يجمعون وكرأس السنبلة يقطعون.","24:25":"وإن لم يكن كذا فمن يكذبني ويجعل كلامي لا شيئا؟].","25:1":"فأجاب بلدد الشوحي:","25:2":"[السلطان والهيبة عنده. هو صانع السلام في أعاليه.","25:3":"هل من عدد لجنوده وعلى من لا يشرق نوره؟","25:4":"فكيف يتبرر الإنسان عند الله وكيف يزكو مولود المرأة؟","25:5":"هوذا نفس القمر لا يضيء والكواكب غير نقية في عينيه.","25:6":"فكم بالحري الإنسان الرمة وابن آدم الدود].","26:1":"فقال أيوب:","26:2":"[كيف أعنت من لا قوة له وخلصت ذراعا لا عز لها؟","26:3":"كيف أشرت على من لا حكمة له وأظهرت الفهم بكثرة؟","26:4":"لمن أعلنت أقوالا ونسمة من خرجت منك؟","26:5":"[الأرواح ترتعد من تحت المياه وسكانها.","26:6":"الهاوية عريانة قدامه والهلاك ليس له غطاء.","26:7":"يمد الشمال على الخلاء ويعلق الأرض على لا شيء.","26:8":"يصر المياه في سحبه فلا يتمزق الغيم تحتها.","26:9":"يحجب وجه كرسيه باسطا عليه سحابه.","26:10":"رسم حدا على وجه المياه عند اتصال النور بالظلمة.","26:11":"أعمدة السماوات ترتعد وترتاع من زجره.","26:12":"بقوته يزعج البحر وبفهمه يسحق رهب.","26:13":"بنفخته السماوات مشرقة ويداه أبدأتا الحية الهاربة.","26:14":"ها هذه أطراف طرقه وما أخفض الكلام الذي نسمعه منه! وأما رعد جبروته فمن يفهم؟].","27:1":"وعاد أيوب ينطق بمثله فقال:","27:2":"[حي هو الله الذي نزع حقي والقدير الذي أمر نفسي","27:3":"إنه ما دامت نسمتي في ونفخة الله في أنفي","27:4":"لن تتكلم شفتاي إثما ولا يلفظ لساني بغش.","27:5":"حاشا لي أن أبرركم! حتى أسلم الروح لا أعزل كمالي عني.","27:6":"تمسكت ببري ولا أرخيه. قلبي لا يعير يوما من أيامي.","27:7":"ليكن عدوي كالشرير ومعاندي كفاعل الشر.","27:8":"لأنه ما هو رجاء الفاجر عندما يقطعه عندما يسلب الله نفسه؟","27:9":"أفيسمع الله صراخه إذا جاء عليه ضيق؟","27:10":"أم يتلذذ بالقدير؟ هل يدعو الله في كل حين؟","27:11":"[إني أعلمكم بيد الله. لا أكتم ما هو عند القدير.","27:12":"ها أنتم كلكم قد رأيتم فلماذا تتبطلون تبطلا قائلين:","27:13":"هذا نصيب الإنسان الشرير من عند الله وميراث العتاة الذي ينالونه من القدير.","27:14":"إن كثر بنوه فللسيف وذريته لا تشبع خبزا.","27:15":"بقيته تدفن بالوباء وأرامله لا تبكي.","27:16":"إن كنز فضة كالتراب وأعد ملابس كالطين","27:17":"فهو يعد والبار يلبسه والبرئ يقسم الفضة.","27:18":"يبني بيته كالعث أو كمظلة صنعها الحارس.","27:19":"يضطجع غنيا ولكنه لا يضم. يفتح عينيه ولا يكون.","27:20":"الأهوال تدركه كالمياه. ليلا تختطفه الزوبعة","27:21":"تحمله الشرقية فيذهب وتجرفه من مكانه.","27:22":"يلقي الله عليه ولا يشفق. من يده يهرب هربا.","27:23":"يصفقون عليه بأيديهم ويصفرون عليه من مكانه.","28:1":"[لأنه يوجد للفضة معدن وموضع للذهب حيث يمحصونه.","28:2":"الحديد يستخرج من التراب والحجر يسكب نحاسا.","28:3":"قد جعل للظلمة نهاية وإلى كل طرف هو يفحص. حجر الظلمة وظل الموت.","28:4":"حفر منجما بعيدا عن السكان. بلا موطئ للقدم. متدلين بعيدين من الناس يتدلدلون.","28:5":"أرض يخرج منها الخبز أسفلها ينقلب كما بالنار.","28:6":"حجارتها هي موضع الياقوت الأزرق وفيها تراب الذهب.","28:7":"سبيل لم يعرفه كاسر ولم تبصره عين باشق","28:8":"ولم تدسه أجراء السبع ولم يسلكه الأسد.","28:9":"إلى الصوان يمد يده. يقلب الجبال من أصولها.","28:10":"ينقر في الصخور سربا وعينه ترى كل ثمين.","28:11":"يمنع رشح الأنهار وأبرز الخفيات إلى النور.","28:12":"[أما الحكمة فمن أين توجد وأين هو مكان الفهم؟","28:13":"لا يعرف الإنسان قيمتها ولا توجد في أرض الأحياء.","28:14":"الغمر يقول: ليست هي في والبحر يقول: ليست هي عندي.","28:15":"لا يعطى ذهب خالص بدلها ولا توزن فضة ثمنا لها.","28:16":"لا توزن بذهب أوفير أو بالجزع الكريم أو الياقوت الأزرق.","28:17":"لا يعادلها الذهب ولا الزجاج ولا تبدل بإناء ذهب إبريز.","28:18":"لا يذكر المرجان أو البلور وتحصيل الحكمة خير من اللآلئ.","28:19":"لا يعادلها ياقوت كوش الأصفر ولا توزن بالذهب الخالص.","28:20":"[فمن أين تأتي الحكمة وأين هو مكان الفهم.","28:21":"إذ أخفيت عن عيون كل حي وسترت عن طير السماء؟","28:22":"الهلاك والموت يقولان: بآذاننا قد سمعنا خبرها.","28:23":"الله يفهم طريقها وهو عالم بمكانها.","28:24":"لأنه هو ينظر إلى أقاصي الأرض. تحت كل السماوات يرى.","28:25":"ليجعل للريح وزنا ويعاير المياه بمقياس.","28:26":"لما جعل للمطر فريضة وسبيلا للصواعق","28:27":"حينئذ رآها وأخبر بها هيأها وأيضا بحث عنها","28:28":"وقال للإنسان: هوذا مخافة الرب هي الحكمة والحيدان عن الشر هو الفهم].","29:1":"وعاد أيوب ينطق بمثله فقال:","29:2":"[يا ليتني كما في الشهور السالفة وكالأيام التي حفظني الله فيها","29:3":"حين أضاء سراجه على رأسي وبنوره سلكت الظلمة.","29:4":"كما كنت في أيام خريفي ورضا الله على خيمتي","29:5":"والقدير بعد معي وحولي غلماني","29:6":"إذ غسلت خطواتي باللبن والصخر سكب لي جداول زيت.","29:7":"حين كنت أخرج إلى الباب في القرية وأهيئ في الساحة مجلسي.","29:8":"رآني الغلمان فاختبأوا والأشياخ قاموا ووقفوا.","29:9":"العظماء أمسكوا عن الكلام ووضعوا أيديهم على أفواههم.","29:10":"صوت الشرفاء اختفى ولصقت ألسنتهم بأحناكهم.","29:11":"لأن الأذن سمعت فطوبتني والعين رأت فشهدت لي.","29:12":"لأني أنقذت المسكين المستغيث واليتيم ولا معين له.","29:13":"بركة الهالك حلت علي وجعلت قلب الأرملة يسر.","29:14":"لبست البر فكساني. كجبة وعمامة كان عدلي.","29:15":"كنت عيونا للعمي وأرجلا للعرج.","29:16":"أب أنا للفقراء ودعوى لم أعرفها فحصت عنها.","29:17":"هشمت أضراس الظالم ومن بين أسنانه خطفت الفريسة.","29:18":"فقلت: إني في وكري أسلم الروح ومثل السمندل أكثر أياما.","29:19":"أصلي كان منبسطا إلى المياه والطل بات على أغصاني.","29:20":"كرامتي بقيت حديثة عندي وقوسي تجددت في يدي.","29:21":"لي سمعوا وانتظروا ونصتوا عند مشورتي.","29:22":"بعد كلامي لم يثنوا وقولي قطر عليهم.","29:23":"وانتظروني مثل المطر وفغروا أفواههم كما للمطر المتأخر.","29:24":"إن ضحكت عليهم لم يصدقوا ونور وجهي لم يعبسوا.","29:25":"كنت أختار طريقهم وأجلس رأسا وأسكن كملك في جيش كمن يعزي النائحين.","30:1":"[وأما الآن فقد ضحك علي من يصغرني في الأيام الذين كنت أستنكف من أن أجعل آباءهم مع كلاب غنمي.","30:2":"قوة أيديهم أيضا ما هي لي. فيهم عجزت الشيخوخة.","30:3":"في العوز والمجاعة مهزولون ينبشون اليابسة التي هي منذ أمس خراب وخربة.","30:4":"الذين يقطفون الملاح عند الشيح وأصول الرتم خبزهم.","30:5":"من الوسط يطردون. يصيحون عليهم كما على لص.","30:6":"للسكن في أودية مرعبة وثقب التراب والصخور.","30:7":"بين الشيح ينهقون. تحت العوسج ينكبون.","30:8":"أبناء الحماقة بل أبناء أناس بلا اسم دحروا من الأرض.","30:9":"[أما الآن فصرت أغنيتهم وأصبحت لهم مثلا!","30:10":"يكرهونني. يبتعدون عني وأمام وجهي لم يمسكوا عن البصق.","30:11":"لأنه أطلق العنان وقهرني فنزعوا الزمام قدامي.","30:12":"عن اليمين السفلة يقومون يزيحون رجلي ويعدون علي طرقهم للبوار.","30:13":"أفسدوا سبلي. أعانوا على سقوطي. لا مساعد عليهم.","30:14":"يأتون كصدع عريض. تحت الهدة يتدحرجون.","30:15":"انقلبت علي أهوال. طردت كالريح نعمتي فعبرت كالسحاب سعادتي.","30:16":"[فالآن انهالت نفسي علي وأخذتني أيام المذلة.","30:17":"الليل ينخر عظامي في وعارقي لا تهجع.","30:18":"بكثرة الشدة تنكر لبسي. مثل جيب قميصي حزمتني.","30:19":"قد طرحني في الوحل فأشبهت التراب والرماد.","30:20":"إليك أصرخ فما تستجيب لي. أقوم فما تنتبه إلي.","30:21":"تحولت إلى جاف من نحوي. بقدرة يدك تضطهدني.","30:22":"حملتني أركبتني الريح وذوبتني تشوها.","30:23":"لأني أعلم أنك إلى الموت تعيدني وإلى بيت ميعاد كل حي.","30:24":"ولكن في الخراب ألا يمد يدا؟ في البلية ألا يستغيث عليها؟","30:25":"[ألم أبك لمن عسر يومه؟ ألم تكتئب نفسي على المسكين؟","30:26":"حينما ترجيت الخير جاء الشر وانتظرت النور فجاء الدجى.","30:27":"أمعائي تغلي ولا تكف. تقدمتني أيام المذلة.","30:28":"اسوددت لكن بلا شمس. قمت في الجماعة أصرخ.","30:29":"صرت أخا للذئاب وصاحبا للنعام.","30:30":"إسود جلدي علي وعظامي احترقت من الحمى في.","30:31":"صار عودي للنوح ومزماري لصوت الباكين.","31:1":"[عهدا قطعت لعيني فكيف أتطلع في عذراء!","31:2":"وما هي قسمة الله من فوق ونصيب القدير من الأعالي؟","31:3":"أليس البوار لعامل الشر والنكر لفاعلي الإثم!","31:4":"أليس هو ينظر طرقي ويحصي جميع خطواتي.","31:5":"إن كنت قد سلكت مع الكذب أو أسرعت رجلي إلى الغش","31:6":"ليزني في ميزان الحق فيعرف الله كمالي.","31:7":"إن حادت خطواتي عن الطريق وذهب قلبي وراء عيني أو لصق عيب بكفي","31:8":"أزرع وغيري يأكل وفروعي تستأصل.","31:9":"[إن غوي قلبي على امرأة أو كمنت على باب قريبي","31:10":"فلتطحن امرأتي لآخر ولينحن عليها آخرون.","31:11":"لأن هذه رذيلة وهي إثم يعرض للقضاة.","31:12":"لأنها نار تأكل حتى إلى الهلاك وتستأصل كل محصولي.","31:13":"[إن كنت رفضت حق عبدي وأمتي في دعواهما علي","31:14":"فماذا كنت أصنع حين يقوم الله؟ وإذا افتقد فبماذا أجيبه؟","31:15":"أوليس صانعي في البطن صانعه وقد صورنا واحد في الرحم؟","31:16":"إن كنت منعت المساكين عن مرادهم أو أفنيت عيني الأرملة","31:17":"أو أكلت لقمتي وحدي فما أكل منها اليتيم!","31:18":"بل منذ صباي كبر عندي كأب ومن بطن أمي هديتها.","31:19":"إن كنت رأيت هالكا لعدم اللبس أو فقيرا بلا كسوة","31:20":"إن لم تباركني حقواه وقد استدفأ بجزة غنمي.","31:21":"إن كنت قد هززت يدي على اليتيم لما رأيت عوني في الباب","31:22":"فلتسقط عضدي من كتفي ولتنكسر ذراعي من قصبتها","31:23":"لأن البوار من الله رعب علي ومن جلاله لم أستطع.","31:24":"[إن كنت قد جعلت الذهب عمدتي أو قلت للإبريز: أنت متكلي.","31:25":"إن كنت قد فرحت إذ كثرت ثروتي ولأن يدي وجدت كثيرا.","31:26":"إن كنت قد نظرت إلى النور حين ضاء أو إلى القمر يسير بالبهاء","31:27":"وغوي قلبي سرا ولثم يدي فمي","31:28":"فهذا أيضا إثم يعرض للقضاة لأني أكون قد جحدت الله من فوق.","31:29":"[إن كنت قد فرحت ببلية مبغضي أو شمت حين أصابه سوء.","31:30":"بل لم أدع حنكي يخطئ في طلب نفسه بلعنة.","31:31":"إن كان أهل خيمتي لم يقولوا: من يأتي بأحد لم يشبع من طعامه؟","31:32":"غريب لم يبت في الخارج. فتحت للمسافر أبوابي.","31:33":"إن كنت قد كتمت كالناس ذنبي لإخفاء إثمي في حضني.","31:34":"إذ رهبت جمهورا غفيرا وروعتني إهانة العشائر فكففت ولم أخرج من الباب!","31:35":"من لي بمن يسمعني؟ هوذا إمضائي. ليجبني القدير. ومن لي بشكوى كتبها خصمي","31:36":"فكنت أحملها على كتفي. كنت أعصبها تاجا لي.","31:37":"كنت أخبره بعدد خطواتي وأدنو منه كشريف.","31:38":"إن كانت أرضي قد صرخت علي وتباكت أتلامها جميعا.","31:39":"إن كنت قد أكلت غلتها بلا فضة أو أطفأت أنفس أصحابها","31:40":"فعوض الحنطة لينبت شوك وبدل الشعير زوان]. تمت أقوال أيوب.","32:1":"فكف هؤلاء الرجال الثلاثة عن مجاوبة أيوب لكونه بارا في عيني نفسه.","32:2":"فحمي غضب أليهو بن برخئيل البوزي من عشيرة رام. على أيوب حمي غضبه لأنه حسب نفسه أبر من الله.","32:3":"وعلى أصحابه الثلاثة حمي غضبه لأنهم لم يجدوا جوابا واستذنبوا أيوب.","32:4":"وكان أليهو قد صبر على أيوب بالكلام لأنهم أكثر منه أياما.","32:5":"فلما رأى أليهو أنه لا جواب في أفواه الرجال الثلاثة حمي غضبه.","32:6":"فقال أليهو بن برخئيل البوزي: [أنا صغير في الأيام وأنتم شيوخ لأجل ذلك خفت وخشيت أن أبدي لكم رأيي.","32:7":"قلت: الأيام تتكلم وكثرة السنين تظهر حكمة.","32:8":"ولكن في الناس روحا ونسمة القدير تعقلهم.","32:9":"ليس الكثيرو الأيام حكماء ولا الشيوخ يفهمون الحق.","32:10":"لذلك قلت اسمعوني. أنا أيضا أبدي رأيي.","32:11":"هئنذا قد صبرت لكلامكم. أصغيت إلى حججكم حتى فحصتم الأقوال.","32:12":"فتأملت فيكم وإذ ليس من حج أيوب ولا جواب منكم لكلامه.","32:13":"فلا تقولوا: قد وجدنا حكمة. الله يغلبه لا الإنسان.","32:14":"فإنه لم يوجه إلي كلامه ولا أرد عليه أنا بكلامكم.","32:15":"تحيروا. لم يجيبوا بعد. انتزع عنهم الكلام.","32:16":"فانتظرت لأنهم لم يتكلموا. لأنهم وقفوا لم يجيبوا بعد.","32:17":"فأجيب أنا أيضا حصتي وأبدي أنا أيضا رأيي.","32:18":"لأني ملآن أقوالا. روح باطني تضايقني.","32:19":"هوذا بطني كخمر لم تفتح. كالزقاق الجديدة يكاد ينشق.","32:20":"أتكلم فأفرج. أفتح شفتي وأجيب.","32:21":"لا أحابين وجه رجل ولا أتملق إنسانا.","32:22":"لأني لا أعرف التملق. لأنه عن قليل يأخذني صانعي.","33:1":"[ولكن اسمع الآن يا أيوب أقوالي واصغ إلى كل كلامي.","33:2":"هئنذا قد فتحت فمي. لساني نطق في حنكي.","33:3":"استقامة قلبي كلامي ومعرفة شفتي هما تنطقان بها خالصة.","33:4":"روح الله صنعني ونسمة القدير أحيتني.","33:5":"إن استطعت فأجبني. أحسن الدعوى أمامي. انتصب.","33:6":"هئنذا حسب قولك عوضا عن الله. أنا أيضا من الطين جبلت.","33:7":"هوذا هيبتي لا ترهبك وجلالي لا يثقل عليك.","33:8":"[إنك قد قلت في مسامعي وصوت أقوالك سمعت.","33:9":"قلت: أنا بريء بلا ذنب. زكي أنا ولا إثم لي.","33:10":"هوذا يطلب علي علل عداوة. يحسبني عدوا له.","33:11":"وضع رجلي في المقطرة. يراقب كل طرقي.","33:12":"[ها إنك في هذا لم تصب. أنا أجيبك. لأن الله أعظم من الإنسان.","33:13":"لماذا تخاصمه؟ لأن كل أموره لا يجاوب عنها.","33:14":"لكن الله يتكلم مرة وباثنتين لا يلاحظ الإنسان.","33:15":"في حلم في رؤيا الليل عند سقوط سبات على الناس في النعاس على المضجع.","33:16":"حينئذ يكشف آذان الناس ويختم على تأديبهم","33:17":"ليحول الإنسان عن عمله ويكتم الكبرياء عن الرجل","33:18":"ليمنع نفسه عن الحفرة وحياته من الزوال بحربة الموت.","33:19":"أيضا يؤدب بالوجع على مضجعه ومخاصمة عظامه دائمة","33:20":"فتكره حياته خبزا ونفسه الطعام الشهي.","33:21":"فيبلى لحمه عن العيان وتنبري عظامه فلا ترى","33:22":"وتقرب نفسه إلى القبر وحياته إلى المميتين.","33:23":"إن وجد عنده مرسل وسيط واحد من ألف ليعلن للإنسان استقامته","33:24":"يترأف عليه ويقول: أطلقه عن الهبوط إلى الحفرة قد وجدت فدية.","33:25":"يصير لحمه أنضر من لحم الصبي ويعود إلى أيام شبابه.","33:26":"يصلي إلى الله فيرضى عنه ويعاين وجهه بهتاف فيرد على الإنسان بره.","33:27":"يغني بين الناس فيقول: قد أخطأت وعوجت المستقيم ولم أجاز عليه.","33:28":"فدى نفسي من العبور إلى الحفرة فترى حياتي النور.","33:29":"[هوذا كل هذه يفعلها الله مرتين وثلاثا بالإنسان","33:30":"ليرد نفسه من الحفرة ليستنير بنور الأحياء.","33:31":"فاصغ يا أيوب واستمع لي. انصت فأنا أتكلم.","33:32":"إن كان عندك كلام فأجبني. تكلم. فإني أريد تبريرك.","33:33":"وإلا فاستمع أنت لي. انصت فأعلمك الحكمة].","34:1":"وقال أليهو:","34:2":"[اسمعوا أقوالي أيها الحكماء واصغوا لي أيها العارفون.","34:3":"لأن الأذن تمتحن الأقوال كما أن الحنك يذوق طعاما.","34:4":"لنمتحن لأنفسنا الحق ونعرف بين أنفسنا ما هو طيب.","34:5":"[لأن أيوب قال: تبررت والله نزع حقي.","34:6":"عند محاكمتي أكذب. جرحي عديم الشفاء من دون ذنب.","34:7":"فأي إنسان كأيوب يشرب الهزء كالماء","34:8":"ويسير متحدا مع فاعلي الإثم وذاهبا مع أهل الشر؟","34:9":"لأنه قال: لا ينتفع الإنسان بكونه مرضيا عند الله.","34:10":"[لأجل ذلك اسمعوا لي يا ذوي الألباب. حاشا لله من الشر وللقدير من الظلم.","34:11":"لأنه يجازي الإنسان على فعله وينيل الرجل كطريقه.","34:12":"فحقا إن الله لا يفعل سوءا والقدير لا يعوج القضاء.","34:13":"من وكله بالأرض ومن صنع المسكونة كلها؟","34:14":"إن جعل عليه قلبه إن جمع إلى نفسه روحه ونسمته","34:15":"يسلم الروح كل بشر جميعا ويعود الإنسان إلى التراب.","34:16":"فإن كان لك فهم فاسمع هذا واصغ إلى صوت كلماتي.","34:17":"ألعل من يبغض الحق يتسلط أم البار الكبير تستذنب.","34:18":"أيقال للملك: يا لئيم وللشرفاء: يا أشرار؟!","34:19":"الذي لا يحابي بوجوه الرؤساء ولا يعتبر غنيا دون فقير. لأنهم جميعهم عمل يديه.","34:20":"بغتة يموتون وفي نصف الليل. يرتج الشعب ويزولون وينزع الأعزاء لا بيد.","34:21":"لأن عينيه على طرق الإنسان وهو يرى كل خطواته.","34:22":"لا ظلام ولا ظل موت حيث تختفي عمال الإثم.","34:23":"لأنه لا يلاحظ الإنسان زمانا للدخول في المحاكمة مع الله.","34:24":"يحطم الأعزاء من دون فحص ويقيم آخرين مكانهم.","34:25":"لكنه يعرف أعمالهم ويقلبهم ليلا فينسحقون.","34:26":"لكونهم أشرارا يصفعهم في مرأى الناظرين.","34:27":"لأنهم انصرفوا من ورائه وكل طرقه لم يتأملوها","34:28":"حتى بلغوا إليه صراخ المسكين فسمع زعقة البائسين.","34:29":"إذا هو سكن فمن يشغب؟ وإذا حجب وجهه فمن يراه سواء كان على أمة أو على إنسان؟","34:30":"حتى لا يملك الفاجر ولا يكون شركا للشعب.","34:31":"[ولكن هل لله قال: احتملت. لا أعود أفسد.","34:32":"ما لم أبصره فأرنيه أنت. إن كنت قد فعلت إثما فلا أعود أفعله؟","34:33":"هل كرأيك يجازيه قائلا: لأنك رفضت فأنت تختار لا أنا. وبما تعرفه تكلم؟","34:34":"ذوو الألباب يقولون لي بل الرجل الحكيم الذي يسمعني يقول:","34:35":"إن أيوب يتكلم بلا معرفة وكلامه ليس بتعقل.","34:36":"فليت أيوب كان يمتحن إلى الغاية من أجل أجوبته كأهل الإثم.","34:37":"لكنه أضاف إلى خطيته معصية. يصفق بيننا ويكثر كلامه على الله].","35:1":"وقال أليهو:","35:2":"[أتحسب هذا حقا؟ قلت: أنا أبر من الله.","35:3":"لأنك قلت: ماذا يفيدك؟ بماذا أنتفع أكثر من خطيتي؟","35:4":"أنا أرد عليك كلاما وعلى أصحابك معك.","35:5":"انظر إلى السماوات وأبصر ولاحظ الغمام. إنها أعلى منك.","35:6":"إن أخطأت فماذا فعلت به؟ وإن كثرت معاصيك فماذا عملت له؟","35:7":"إن كنت بارا فماذا أعطيته أو ماذا يأخذه من يدك؟","35:8":"لرجل مثلك شرك ولابن آدم برك.","35:9":"من كثرة المظالم يصرخون. يستغيثون من ذراع الأعزاء.","35:10":"ولم يقولوا: أين الله صانعي مؤتي الأغاني في الليل؟","35:11":"الذي يعلمنا أكثر من وحوش الأرض ويجعلنا أحكم من طيور السماء.","35:12":"ثم يصرخون من كبرياء الأشرار ولا يستجيب.","35:13":"ولكن الله لا يسمع كذبا والقدير لا ينظر إليه.","35:14":"فإذا قلت إنك لست تراه فالدعوى قدامه فاصبر له.","35:15":"وأما الآن فلأن غضبه لا يطالب ولا يبالي بكثرة الزلات","35:16":"فغر أيوب فاه بالباطل وكبر الكلام بلا معرفة].","36:1":"وعاد أليهو فقال:","36:2":"[اصبر علي قليلا فأبدي لك أنه بعد لأجل الله كلام.","36:3":"أحمل معرفتي من بعيد وأنسب برا لصانعي.","36:4":"حقا لا يكذب كلامي. صحيح المعرفة عندك.","36:5":"[هوذا الله عزيز ولكنه لا يرذل أحدا. عزيز قدرة القلب.","36:6":"لا يحيي الشرير بل يجري قضاء البائسين.","36:7":"لا يحول عينيه عن البار بل مع الملوك يجلسهم على الكرسي أبدا فيرتفعون.","36:8":"إن أوثقوا بالقيود إن أخذوا في حبال الذل","36:9":"فيظهر لهم أفعالهم ومعاصيهم لأنهم تجبروا","36:10":"ويفتح آذانهم للإنذار ويأمر بأن يرجعوا عن الإثم.","36:11":"إن سمعوا وأطاعوا قضوا أيامهم بالخير وسنيهم بالنعم.","36:12":"وإن لم يسمعوا فبحربة الموت يزولون ويموتون بعدم المعرفة.","36:13":"أما فجار القلب فيذخرون غضبا. لا يستغيثون إذا هو قيدهم.","36:14":"تموت نفسهم في الصبا وحياتهم بين المأبونين.","36:15":"ينجي البائس في ذله ويفتح آذانهم في الضيق.","36:16":"[وأيضا يقودك من وجه الضيق إلى رحب لا حصر فيه ويملأ مؤونة مائدتك دهنا.","36:17":"حجة الشرير أكملت فالحجة والقضاء يمسكانك.","36:18":"عند غضبه لعله يقودك بصفقة. فكثرة الفدية لا تفكك.","36:19":"هل يعتبر غناك؟ لا التبر ولا جميع قوى الثروة!","36:20":"لا تشتاق إلى الليل الذي يرفع شعوبا من مواضعهم.","36:21":"احذر. لا تلتفت إلى الإثم لأنك اخترت هذا على الذل.","36:22":"[هوذا الله يتعالى بقدرته. من مثله معلما؟","36:23":"من فرض عليه طريقه أو من يقول له: قد فعلت شرا؟","36:24":"اذكر أن تعظم عمله الذي يترنم به الناس.","36:25":"كل إنسان يبصر به. الناس ينظرونه من بعيد.","36:26":"هوذا الله عظيم ولا نعرفه وعدد سنيه لا يفحص.","36:27":"لأنه يجذب قطرات الماء. تسح مطرا من ضبابها","36:28":"الذي تهطله السحب وتقطره على أناس كثيرين.","36:29":"فهل يعلل أحد عن شق الغيم أو قصيف مظلته؟","36:30":"هوذا بسط نوره على نفسه ثم يتغطى بأصول البحر.","36:31":"لأنه بهذه يدين الشعوب ويرزق القوت بكثرة.","36:32":"يغطي كفيه بالنور ويأمره على العدو.","36:33":"يخبر به رعده المواشي أيضا بصعوده.","37:1":"[فلهذا اضطرب قلبي وخفق من موضعه.","37:2":"اسمعوا سماعا رعد صوته والدوي الخارج من فمه.","37:3":"تحت كل السماوات يطلقها كذا نوره إلى أطراف الأرض.","37:4":"بعد يزمجر صوت يرعد بصوت جلاله ولا يؤخرها إذ سمع صوته.","37:5":"الله يرعد بصوته عجبا. يصنع عظائم لا ندركها.","37:6":"لأنه يقول للثلج: اسقط على الأرض. كذا لوابل المطر وابل أمطار عزه.","37:7":"يختم على يد كل إنسان ليعلم كل الناس خالقهم","37:8":"فتدخل الحيوانات المآوي وتستقر في أوجرتها.","37:9":"من الجنوب تأتي الأعصار ومن الشمال البرد.","37:10":"من نسمة الله يجعل الجمد وتتضيق سعة المياه.","37:11":"أيضا بري يطرح الغيم. يبدد سحاب نوره.","37:12":"فهي مدورة متقلبة بإدارته لتفعل كل ما يأمر به على وجه الأرض المسكونة","37:13":"سواء كان للتأديب أو لأرضه أو للرحمة يرسلها.","37:14":"[انصت إلى هذا يا أيوب وقف وتأمل بعجائب الله.","37:15":"أتدرك انتباه الله إليها أو إضاءة نور سحابه.","37:16":"أتدرك موازنة السحاب معجزات الكامل المعارف.","37:17":"كيف تسخن ثيابك إذا سكنت الأرض من ريح الجنوب.","37:18":"هل صفحت معه الجلد الممكن كالمرآة المسبوكة؟","37:19":"علمنا ما نقول له. إننا لا نحسن الكلام بسبب الظلمة!","37:20":"هل يقص عليه كلامي إذا تكلمت؟ هل ينطق الإنسان لكي يبتلع؟","37:21":"والآن لا يرى النور الباهر الذي هو في الجلد ثم تعبر الريح فتنقيه.","37:22":"من الشمال يأتي ذهب. عند الله جلال مرهب.","37:23":"القدير لا ندركه. عظيم القوة والحق وكثير البر. لا يجاوب.","37:24":"لذلك فلتخفه الناس. كل حكيم القلب لا يراعي].","38:1":"فقال الرب لأيوب من العاصفة:","38:2":"[من هذا الذي يظلم القضاء بكلام بلا معرفة؟","38:3":"اشدد الآن حقويك كرجل فإني أسألك فتعلمني.","38:4":"أين كنت حين أسست الأرض؟ أخبر إن كان عندك فهم.","38:5":"من وضع قياسها؟ لأنك تعلم! أو من مد عليها مطمارا؟","38:6":"على أي شيء قرت قواعدها أو من وضع حجر زاويتها","38:7":"عندما ترنمت كواكب الصبح معا وهتف جميع بني الله؟","38:8":"[ومن حجز البحر بمصاريع حين اندفق فخرج من الرحم.","38:9":"إذ جعلت السحاب لباسه والضباب قماطه","38:10":"وجزمت عليه حدي وأقمت له مغاليق ومصاريع","38:11":"وقلت: إلى هنا تأتي ولا تتعدى وهنا تتخم كبرياء لججك؟","38:12":"[هل في أيامك أمرت الصبح؟ هل عرفت الفجر موضعه","38:13":"ليمسك بأطراف الأرض فينفض الأشرار منها؟","38:14":"تتحول كطين الخاتم وتقف كأنها لابسة.","38:15":"ويمنع عن الأشرار نورهم وتنكسر الذراع المرتفعة.","38:16":"[هل انتهيت إلى ينابيع البحر أو في مقصورة الغمر تمشيت؟","38:17":"هل انكشفت لك أبواب الموت أو عاينت أبواب ظل الموت؟","38:18":"هل أدركت عرض الأرض؟ أخبر إن عرفته كله!","38:19":"[أين الطريق إلى حيث يسكن النور والظلمة أين مقامها","38:20":"حتى تأخذها إلى تخومها وتعرف سبل بيتها؟","38:21":"تعلم لأنك حينئذ كنت قد ولدت وعدد أيامك كثير!","38:22":"[أدخلت إلى خزائن الثلج أم أبصرت مخازن البرد","38:23":"التي أبقيتها لوقت الضر ليوم القتال والحرب؟","38:24":"في أي طريق يتوزع النور وتتفرق الريح الشرقية على الأرض؟","38:25":"من فرع قنوات للهطل وطريقا للصواعق","38:26":"ليمطر على أرض حيث لا إنسان على قفر لا أحد فيه","38:27":"ليروي البلقع والخلاء وينبت مخرج العشب؟","38:28":"[هل للمطر أب ومن ولد مآجل الطل؟","38:29":"من بطن من خرج الجليد؟ صقيع السماء من ولده؟","38:30":"كحجر صارت المياه. اختبأت. وتلكد وجه الغمر.","38:31":"[هل تربط أنت عقد الثريا أو تفك ربط الجبار؟","38:32":"أتخرج المنازل في أوقاتها وتهدي النعش مع بناته؟","38:33":"هل عرفت سنن السماوات أو جعلت تسلطها على الأرض؟","38:34":"أترفع صوتك إلى السحب فيغطيك فيض المياه؟","38:35":"أترسل البروق فتذهب وتقول لك: ها نحن؟","38:36":"من وضع في الطخاء حكمة أو من أظهر في الشهب فطنة؟","38:37":"من يحصي الغيوم بالحكمة ومن يسكب أزقاق السماوات","38:38":"إذ ينسبك التراب سبكا ويتلاصق الطين؟","38:39":"[أتصطاد للبوة فريسة أم تشبع نفس الأشبال","38:40":"حين تربض في عرينها وتكمن في غابتها للكمون؟","38:41":"من يهيئ للغراب صيده إذ تنعب فراخه إلى الله وتتردد لعدم القوت؟","39:1":"[أتعرف وقت ولادة وعول الصخور أو تلاحظ مخاض الأيائل؟","39:2":"أتحسب الشهور التي تكملها أو تعلم ميعاد ولادتهن؟","39:3":"يبركن ويضعن أولادهن. يدفعن أوجاعهن.","39:4":"تبلغ أولادهن. تربو في البرية. تخرج ولا تعود إليهن.","39:5":"[من سرح الفراء حرا ومن فك ربط حمار الوحش؟","39:6":"الذي جعلت البرية بيته والسباخ مسكنه.","39:7":"يضحك على جمهور القرية. لا يسمع زجر السائق.","39:8":"دائرة الجبال مرعاه وعلى كل خضرة يفتش.","39:9":"[أيرضى الثور الوحشي أن يخدمك أم يبيت عند معلفك؟","39:10":"أتربط الثور الوحشي بحبل إلى خط المحراث أم يمهد الأودية وراءك؟","39:11":"أتثق به لأن قوته عظيمة أو تترك له تعبك؟","39:12":"أتأتمنه أنه يأتي بزرعك ويجمع إلى بيدرك؟","39:13":"[جناح النعامة يرفرف. أفهو منكب رؤوف أم ريش؟","39:14":"لأنها تترك بيضها وتحميه في التراب","39:15":"وتنسى أن الرجل تضغطه أو حيوان البر يدوسه!","39:16":"تقسو على أولادها كأنها ليست لها. باطل تعبها بلا أسف.","39:17":"لأن الله قد أنساها الحكمة ولم يقسم لها فهما.","39:18":"عندما تحوذ نفسها إلى العلاء تضحك على الفرس وعلى راكبه.","39:19":"[هل أنت تعطي الفرس قوته وتكسو عنقه عرفا؟","39:20":"أتوثبه كجرادة؟ نفخ منخره مرعب.","39:21":"يبحث في الوادي ويقفز ببأس. يخرج للقاء الأسلحة.","39:22":"يضحك على الخوف ولا يرتاع ولا يرجع عن السيف.","39:23":"عليه تصل السهام وسنان الرمح والحربة.","39:24":"في وثبه وغضبه يلتهم الأرض ولا يؤمن أنه صوت البوق.","39:25":"عند نفخ البوق يقول: هه! ومن بعيد يستروح القتال صياح القواد والهتاف.","39:26":"[أمن فهمك يستقل العقاب وينشر جناحيه نحو الجنوب؟","39:27":"أو بأمرك يحلق النسر ويعلي وكره؟","39:28":"يسكن الصخر ويبيت على سن الصخر والمعقل.","39:29":"من هناك يتحسس قوته. تبصره عيناه من بعيد.","39:30":"فراخه تحسو الدم وحيثما تكن القتلى فهناك هو].","40:1":"وقال الرب لأيوب:","40:2":"[هل يخاصم القدير موبخه أم المحاج الله يجاوبه؟].","40:3":"فأجاب أيوب الرب:","40:4":"[ها أنا حقير فماذا أجاوبك؟ وضعت يدي على فمي.","40:5":"مرة تكلمت فلا أجيب ومرتين فلا أزيد].","40:6":"فقال الرب لأيوب من العاصفة:","40:7":"[الآن شد حقويك كرجل. أسألك فتعلمني.","40:8":"لعلك تناقض حكمي. تستذنبني لتتبرر أنت!","40:9":"هل لك ذراع كما لله وبصوت مثل صوته ترعد؟","40:10":"تزين الآن بالجلال والعز والبس المجد والبهاء.","40:11":"فرق فيض غضبك وانظر كل متعظم واخفضه.","40:12":"انظر إلى كل متعظم وذلله ودس الأشرار في مكانهم.","40:13":"اطمرهم في التراب معا واحبس وجوههم في الظلام.","40:14":"فأنا أيضا أحمدك لأن يمينك تخلصك.","40:15":"[هوذا فرس البحر الذي صنعته معك. يأكل العشب مثل البقر.","40:16":"ها هي قوته في متنيه وشدته في عضل بطنه.","40:17":"يخفض ذنبه كأرزة. عروق فخذيه مضفورة.","40:18":"عظامه أنابيب نحاس وأضلاعه حديد مطرق.","40:19":"هو أول أعمال الله. الذي صنعه أعطاه سيفه.","40:20":"لأن الجبال تخرج له مرعى وجميع وحوش البر تلعب هناك.","40:21":"تحت السدرات يضطجع في ستر القصب والغمقة.","40:22":"تظلله السدرات بظلها. يحيط به صفصاف السواقي.","40:23":"هوذا النهر يفيض فلا يفر هو. يطمئن ولو اندفق الأردن في فمه.","40:24":"هل يؤخذ من أمامه؟ هل يثقب أنفه بخزامة؟","41:1":"[أتصطاد التمساح بشص أو تضغط لسانه بحبل؟","41:2":"أتضع أسلة في خطمه أم تثقب فكه بخزامة؟","41:3":"أيكثر التضرعات إليك أم يتكلم معك باللين؟","41:4":"هل يقطع معك عهدا فتتخذه عبدا مؤبدا؟","41:5":"أتلعب معه كالعصفور أو تربطه لأجل فتياتك؟","41:6":"هل تحفر جماعة الصيادين لأجله حفرة أو يقسمونه بين الكنعانيين؟","41:7":"أتملأ جلده حرابا ورأسه بإلال السمك؟","41:8":"ضع يدك عليه. لا تعد تذكر القتال!","41:9":"هوذا الرجاء به كاذب. ألا يكب أيضا برؤيته.","41:10":"ليس من شجاع يوقظه فمن يقف إذا بوجهي؟","41:11":"من تقدمني فأوفيه؟ ما تحت كل السماوات هو لي.","41:12":"[لا أسكت عن أعضائه وخبر قوته وبهجة عدته.","41:13":"من يكشف وجه لبسه ومن يدنو من مثنى لجمته؟","41:14":"من يفتح مصراعي فمه؟ دائرة أسنانه مرعبة.","41:15":"فخره مجان مانعة محكمة مضغوطة بخاتم.","41:16":"الواحد يمس الآخر فالريح لا تدخل بينها.","41:17":"كل منها ملتصق بصاحبه متجمدة لا تنفصل.","41:18":"عطاسه يبعث نورا وعيناه كهدب الصبح.","41:19":"من فمه تخرج مصابيح. شرار نار تتطاير منه.","41:20":"من منخريه يخرج دخان كأنه من قدر منفوخ أو من مرجل.","41:21":"نفسه يشعل جمرا ولهيب يخرج من فمه.","41:22":"في عنقه تبيت القوة وأمامه يدوس الهول.","41:23":"مطاوي لحمه متلاصقة مسبوكة عليه لا تتحرك.","41:24":"قلبه صلب كالحجر وقاس كالرحى.","41:25":"عند نهوضه تفزع الأقوياء. من المخاوف يتيهون.","41:26":"سيف الذي يلحقه لا يقوم ولا رمح ولا حربة ولا درع.","41:27":"يحسب الحديد كالتبن والنحاس كالعود النخر.","41:28":"لا يستفزه نبل القوس. حجارة المقلاع ترجع عنه كالقش.","41:29":"يحسب المطرقة كقش ويضحك على اهتزاز الرمح.","41:30":"تحته قطع خزف حادة. يمدد نورجا على الطين.","41:31":"يجعل العمق يغلي كالقدر ويجعل البحر كقدر عطارة.","41:32":"يضيء السبيل وراءه فيحسب اللج أشيب.","41:33":"ليس له في الأرض نظير. صنع لعدم الخوف.","41:34":"يشرف على كل متعال. هو ملك على كل بني الكبرياء].","42:1":"فأجاب أيوب الرب:","42:2":"[قد علمت أنك تستطيع كل شيء ولا يعسر عليك أمر.","42:3":"فمن ذا الذي يخفي القضاء بلا معرفة! ولكني قد نطقت بما لم أفهم. بعجائب فوقي لم أعرفها.","42:4":"اسمع الآن وأنا أتكلم. أسألك فتعلمني.","42:5":"بسمع الأذن قد سمعت عنك والآن رأتك عيني.","42:6":"لذلك أرفض وأندم في التراب والرماد].","42:7":"وكان بعدما تكلم الرب مع أيوب بهذا الكلام أن الرب قال لأليفاز التيماني: [قد احتمى غضبي عليك وعلى كلا صاحبيك لأنكم لم تقولوا في الصواب كعبدي أيوب.","42:8":"والآن فخذوا لأنفسكم سبعة ثيران وسبعة كباش واذهبوا إلى عبدي أيوب وأصعدوا محرقة لأجل أنفسكم وعبدي أيوب يصلي من أجلكم لأني أرفع وجهه لئلا أصنع معكم حسب حماقتكم لأنكم لم تقولوا في الصواب كعبدي أيوب].","42:9":"فذهب أليفاز التيماني وبلدد الشوحي وصوفر النعماتي وفعلوا كما قال الرب لهم. ورفع الرب وجه أيوب.","42:10":"ورد الرب سبي أيوب لما صلى لأجل أصحابه وزاد الرب على كل ما كان لأيوب ضعفا.","42:11":"فجاء إليه كل إخوته وكل أخواته وكل معارفه من قبل وأكلوا معه خبزا في بيته ورثوا له وعزوه عن كل الشر الذي جلبه الرب عليه وأعطاه كل منهم قسيطة واحدة وكل واحد قرطا من ذهب.","42:12":"وبارك الرب آخرة أيوب أكثر من أولاه. وكان له أربعة عشر ألفا من الغنم وستة آلاف من الإبل وألف زوج من البقر وألف أتان.","42:13":"وكان له سبعة بنين وثلاث بنات.","42:14":"وسمى اسم الأولى يميمة واسم الثانية قصيعة واسم الثالثة قرن هفوك.","42:15":"ولم توجد نساء جميلات كبنات أيوب في كل الأرض. وأعطاهن أبوهن ميراثا بين إخوتهن.","42:16":"وعاش أيوب بعد هذا مئة وأربعين سنة ورأى بنيه وبني بنيه إلى أربعة أجيال.","42:17":"ثم مات أيوب شيخا وشبعان الأيام."};
